INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4626361, 549, '/n5mpcC4lqLtZNPIjjlsFFl3kbUT.jpg', 'In stark black and white, Jean-Michel Basquiat (Jeffrey Wright) sits in a window booth at the diner he frequents, hand resting on a menu, his brooding gaze lowered, while a quiet New York street and a "Today''s Specials" sign sit behind him.', 'claude-sonnet-5-5')
