INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 3811975, 422, '/A96Z3UVnfVAOAXGe98KYc8Yi1yh.jpg', 'In a tiled interior, Marcello Mastroianni''s bespectacled Guido Anselmi smirks playfully at a woman in a white feather hat and fur collar with a dotted veil, who presses a finger toward her lips, a flirtatious, conspiratorial moment in this black-and-white scene from 8½.', 'claude-sonnet-5-5')
