INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5307075, 694, '/eHiEzcmcQXgjDq5MF4CPW1HHx2l.jpg', 'An Adler typewriter with a blank sheet sits on a dark wooden table in the Overlook Hotel''s lounge, with a smoldering ashtray, cigarettes, and a cup of pencils nearby. It is Jack Torrance''s writing station, still and ominous before his novel unravels into madness.', 'claude-sonnet-5-5')
