INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5058750, 694, '/t2YL7iZr5cWzNv7WLZWCwQgIx1l.jpg', 'The sprawling, lodge-style Overlook Hotel sits at the foot of a patchy, snow-streaked mountain under a clear blue sky, with cars parked out front, in a calm establishing shot that belies the isolation and dread to come in *The Shining*.', 'claude-sonnet-5-5')
