INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5386594, 583, '/3mWLIbAlu1R87N7JGnsjAM9JtI6.jpg', 'A cracked-fresco promotional parody of The Last Supper, with the Life of Brian cast lined up behind a table wearing golden halos, a Roman centurion beside them, and "Romani ite domum" graffiti scrawled on the wall below, while a dove carries a "We Love Biggus Dickus" banner overhead.', 'claude-sonnet-5-5')
