INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 3436223, 779, '/rg3hBiQbDet8uNQkgfbpk7306p8.jpg', 'In Dreyer''s *Vampyr*, a pale young woman, most likely the ailing Léone (Sybille Schmitz), lies motionless on an ornate wooden bench in the manor, while the looming shadow of a scythe falls across the wall above her in a haunting, deathly stillness.', 'claude-sonnet-5-5')
