INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 728987, 975, '/3G9YiVm0bQB1XyyyiDzfeNCiFLw.jpg', 'In a stark black-and-white close-up, Kirk Douglas as Colonel Dax stands grim-faced in his Adrian helmet and "701" collar tabs, eyes lowered, while blurred soldiers stand at attention behind him in a somber, solemn assembly.', 'claude-sonnet-5-5')
