INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 935452, 935, '/dqmujMrdDn6LFkODiDlc5iJBf5p.jpg', 'In the Pentagon War Room, beneath the enormous angled world maps, officials and generals brawl in a pie fight, wading through splattered cream across the floor, in this cut scene from Kubrick''s Cold War satire, in stark black and white.', 'claude-sonnet-5-5')
