INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5148599, 2487, '/zCQQ2qRcnq9tgFcIEjop95Ok1kx.jpg', 'Two young women in traditional kimono, one in bold navy-and-white stripes and the other in vivid red, face each other on a rocky seaside bluff above a deep blue ocean, as the smiling one offers a small sweet on a stick. The vivid, sunlit palette does not match the 1973 film''s look, so the scene cannot be placed in its plot.', 'claude-sonnet-5-5')
