INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4862631, 2487, '/ibntqLx5n7iByezuZ9ZVF4gx1K1.jpg', 'Sunlit autumn reeds in golden-brown tones crowd the foreground of a glittering lake, with a small wooden boat half-hidden among them and hazy rooftops of a town beyond, a quiet, still moment in Lady Snowblood''s Meiji-era landscape.', 'claude-sonnet-5-5')
