INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 700236, 6977, '/izYudgEIOiKFznbeTjnYeDQfxO1.jpg', 'Anton Chigurh (Javier Bardem), with his bowl-cut hair and dark denim jacket, stares coolly at the gas station proprietor in the cluttered store, in the tense coin-toss scene where he questions the old man with unsettling calm.', 'claude-sonnet-5-5')
