INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4104659, 8016, '/u7XziFIhKZBZJAWCXUP6GGvgH5S.jpg', 'Seen from behind, young Edmund walks alone down a narrow path cut through rubble-strewn streets, with the gutted, bombed-out buildings of postwar Berlin looming ahead in stark black-and-white, a picture of desolation and isolation.', 'claude-sonnet-5-5')
