INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4671985, 5336, '/54c7cKZrNm1MUhj065yAcUFyreB.jpg', 'Two young women with decorative hairclips, one red-haired and one blonde, sit side by side in a dim room, staring warily and tensely ahead, evoking the fear and captivity of the captured victims in Pasolini''s *Salò*.', 'claude-sonnet-5-5')
