INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 3942223, 5558, '/3OlbL6DqXWP2zCbsQTNkFlwCpON.jpg', 'Awake and sleepless in their striped-wallpaper bedroom, Mr. Foucauld (Jean-Claude Brialy) pours a glass of water from a carafe while his red-haired wife (Monica Vitti) sleeps beside him, capturing the uneasy, dreamlike calm before his strange nocturnal visitations.', 'claude-sonnet-5-5')
