INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 2006823, 5000, '/eVbAzpUr8qhs9C47FsoZF3kenTO.jpg', 'On a wooded country path, young Michel (Georges Poujouly) in cap and shorts holds a leashed dog and looks down, while little Paulette (Brigitte Fossey) in a polka-dot dress gazes up at him, in a quiet black-and-white moment of wary childhood companionship.', 'claude-sonnet-5-5')
