INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 117694, 8074, '/wdiymtPaEsQuMEMtgj55AcR5b5w.jpg', 'In the film''s closing macro shot, brightly colored consumer-product boxes (Ajax, Dash, Lava, Omo, Lustucru) stand on a grassy meadow and form a miniature city, Godard''s satirical image of Paris as consumer culture.', 'claude-sonnet-5-5')
