INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5178324, 6977, '/hlYpKv36juHwX52nHjf6ozkFNlN.jpg', 'Llewelyn Moss (Josh Brolin), in a straw cowboy hat and plaid shirt, grips the strap of a rifle slung over his shoulder while squinting warily across the vast, dry Texas plain beneath an overcast sky, during his pronghorn hunt.', 'claude-sonnet-5-5')
