INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 5027675, 8740, '/d0p6YGUdGJYpSflHb42MqQCaAVl.jpg', 'A black-and-white missing-person flyer headed "Wie heeft deze vrouw gezien?" ("Who has seen this woman?") shows a smiling, curly-haired Saskia Wagter, the face Rex circulates in his desperate three-year search after her abduction, set against a plain pale background.', 'claude-sonnet-5-5')
