INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4978397, 4946, '/vOQNvoN4LADzF0NKrXMZ3x81JrG.jpg', 'Jean-Paul (Alain Delon), shirtless in orange swim trunks and standing in the water, rubs the back of Marianne (Romy Schneider), who lies in a black swimsuit along the pool''s edge, in the languid, sensual opening scene by the sunlit Saint-Tropez villa pool.', 'claude-sonnet-5-5')
