INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4057223, 6977, '/uJlh7MAToLNA2eoTmk2yem0e81l.jpg', 'Anton Chigurh (Javier Bardem), bowl-cut hair and dark jacket, peers coolly through a narrow gap in a dim motel-style room, blood spatter on the wall beside him, radiating quiet, predatory menace.', 'claude-sonnet-5-5')
