INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 126810, 5156, '/drA8fgR8xhqRNXATInYXL831OvE.jpg', 'Antonio, played by Lamberto Maggiorani, lifts his redeemed bicycle indoors in his cap and work jacket, smiling down warmly at his son Bruno, who gazes up at him with admiration, in a hopeful moment before the theft.', 'claude-sonnet-5-5')
