INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4189775, 8741, '/noCrkLkIHngIo4z31lZJBeCOHnw.jpg', 'In the dim brig of the troopship, Pvt. Witt (Jim Caviezel) sits shirtless on a bunk, lit by a small flame, while First Sergeant Welsh (Sean Penn) watches him through the steel mesh, a tense, quiet confrontation after Witt''s AWOL.', 'claude-sonnet-5-5')
