INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 700201, 6977, '/kd9jFTTabg4xJpHDgxY0h8F9BzG.jpg', 'Anton Chigurh, played by Javier Bardem, crouches in a dim motel room and aims his silenced shotgun past a blood-spattered wall, his bowl-cut head tilted and his expression cold and methodical as he hunts his prey.', 'claude-sonnet-5-5')
