INSERT INTO T_WC_TMDB_IMAGE_CAPTION (TABLE_SOURCE, ID_ROW, ID_ENTITY, IMAGE_PATH, CAPTION, CAPTION_MODEL) VALUES ('movie', 4360806, 1553, '/5rXy5Zf9c9FWbQ6wIGcLkMgc31p.jpg', 'In a dim, warm-lit room, a white-haired older man, apparently Robert Seyr (Niels Arestrup), tenderly kisses the forehead of his dark-haired son Thomas (Romain Duris), who wears headphones and shuts his eyes in a rare moment of father-son intimacy.', 'claude-sonnet-5-5')
